// Turn the form submission into the same shape as the keyword matrix.
const list = (v) => String(v || '').split(/[;,\n]/).map(s => s.trim()).filter(Boolean);
const f = $input.first().json;
const maxItems = Number(f['Max profiles per keyword']) || 25;
return list(f['Job titles / keywords']).map(keyword => ({ json: {
  keyword,
  priority: 'P1',
  headcount: list(f['Company headcount (e.g. 51-200, 201-500)']),
  industries: list(f['Industries']),
  locations: list(f['Locations']),
  maxItems,
}}));

// Build the Apify (automly/linkedin-people-search-scraper) input from one matrix row.
// NOTE: this actor has no company-headcount / industry facets, so those matrix columns are
// recorded for reference only; the ICP is expressed through job title + location.
return $input.all().map(item => {
  const r = item.json;
  const apifyInput = {
    jobTitles: [r.keyword],
    locations: r.locations || [],
    maxResults: r.maxItems || 25,
    maxResultsPerSearch: r.maxItems || 25,
  };
  return { json: { keyword: r.keyword, priority: r.priority, apifyInput } };
});

// Keep the RAW scraped record (raw_json) plus the main fields flattened for the sheet.
const meta = $('Build Apify Input').all();
return $input.all().map(item => {
  const p = item.json || {};
  const src = meta[(item.pairedItem && item.pairedItem.item) || 0]?.json || {};
  const parts = String(p.name || '').trim().split(/\s+/);
  const headline = p.headline || '';
  const m = headline.match(/^(.*?)\s+(?:at|@)\s+(.*)$/i);
  return { json: {
    scraped_at: new Date().toISOString(),
    keyword: src.keyword || '',
    priority: src.priority || '',
    first_name: parts[0] || '',
    last_name: parts.slice(1).join(' '),
    headline,
    current_title: m ? m[1] : headline,
    current_company: p.company || (m ? m[2] : ''),
    location: p.location || '',
    linkedin_url: p.linkedinUrl || '',
    profile_id: p.publicIdentifier || '',
    school: p.school || '',
    connections: p.connections || '',
    raw_json: JSON.stringify(p),
  }};
});
